<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/../includes/reports.php';
$user=require_business(); $db=db(); $error=null; $data=null; $print=false; $filters=null;
try {
    if ($_SERVER['REQUEST_METHOD']!=='GET') { http_response_code(405); header('Allow: GET'); throw new InvalidArgumentException('Reports are read-only.'); }
    $filters=report_filters($_GET); $export=sale_text($_GET,'export'); $printValue=sale_text($_GET,'print','0');
    if (!in_array($export,['','csv'],true) || !in_array($printValue,['0','1'],true)) { throw new InvalidArgumentException('Choose a valid export or print option.'); }
    $print=$printValue==='1'; $db->beginTransaction();
    if ($export==='csv') {
        // Build before sending headers so failures never produce a partial CSV.
        $stream=fopen('php://temp','w+'); report_csv($db,(int)$user['business_id'],$user['business_name'],$filters,$stream); $db->commit();
        rewind($stream); header('Content-Type: text/csv; charset=UTF-8');
        $filename='profitpocket_'.($filters['tab']==='utang'?'receivables':$filters['tab']).'_'.$filters['period']['start']->format('Y-m-d').'_'.$filters['period']['end']->format('Y-m-d').'.csv';
        header('Content-Disposition: attachment; filename="'.$filename.'"'); echo "\xEF\xBB\xBF"; fpassthru($stream); fclose($stream); exit;
    }
    $data=report_data($db,(int)$user['business_id'],$filters); $listing=report_listing($db,(int)$user['business_id'],$filters,$print);
    $options=report_query($db,'SELECT expense_category_id,category_name FROM expense_categories WHERE business_id=? ORDER BY category_name',[$user['business_id']])->fetchAll(); $db->commit();
} catch (InvalidArgumentException $e) { if (http_response_code()===200) { http_response_code(400); } $error=$e->getMessage();
} catch (Throwable $e) { error_log('ProfitPocket: report query failed, code '.$e->getCode()); http_response_code(503); $error='Reports are temporarily unavailable. Please try again.'; }
if ($db->inTransaction()) { $db->rollBack(); }
$page_title='Financial Reports'; $active_page='reports'; $dashboard_layout=true;
$titles=['sales'=>'Sales Report','expenses'=>'Expense Report','profit'=>'Profit Report','utang'=>'Customer Receivables'];
require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/navbar.php';
?>
<main class="dashboard-main reports-page <?= $print?'report-print-view':'' ?>" id="dashboard-content">
    <div class="dashboard-heading"><div><h1>Financial Reports</h1><p>Understand your sales, expenses, and business profits.</p></div>
    <?php if ($data): ?><div class="report-heading-actions report-no-print"><span class="period-label"><?= e($filters['period']['label']) ?></span>
        <?php if ($print): ?><button type="button" class="btn btn-primary btn-sm" data-report-print>Print report</button><a class="btn btn-outline-secondary btn-sm" href="<?= e(report_url($filters)) ?>">Back to reports</a>
        <?php else: ?><div class="dropdown"><button class="btn btn-outline-secondary btn-sm dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">Export Report</button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="<?= e(report_url($filters,['export'=>'csv'])) ?>">Download <?= e($titles[$filters['tab']]) ?> CSV</a></li><li><a class="dropdown-item" href="<?= e(report_url($filters,['print'=>1])) ?>" target="_blank" rel="noopener">Print <?= e($titles[$filters['tab']]) ?></a></li></ul></div><?php endif; ?>
    </div><?php endif; ?></div>
    <?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><a class="btn btn-outline-secondary" href="<?= e(app_url('user/reports.php')) ?>">Return to reports</a>
    <?php else: ?>
    <div class="report-print-heading"><h2><?= e($user['business_name']) ?> · <?= e($titles[$filters['tab']]) ?></h2><p><?= e($filters['period']['label']) ?> · Asia/Manila · Generated <?= e(date('j M Y, g:i A')) ?></p></div>
    <section class="dashboard-panel filter-panel report-no-print" aria-label="Reporting period"><form method="get" class="dashboard-filter">
        <input type="hidden" name="tab" value="<?= e($filters['tab']) ?>">
