        <div class="date-controls" id="custom-dates"><div><label for="start">From</label><input type="date" class="form-control form-control-sm" name="start" id="start" value="<?= e($filters['period']['start']->format('Y-m-d')) ?>"></div><span class="date-range-separator">–</span><div><label for="end">To</label><input type="date" class="form-control form-control-sm" name="end" id="end" value="<?= e($filters['period']['end']->format('Y-m-d')) ?>"></div></div>
