    </section>
    <div class="overview-notes"><p>Summary and chart cover the entire selected period. Table filters affect only the selected table, CSV and print rows. Repayments are collections, not additional sales.</p><?php if ($data['zero_cost']): ?><p class="cost-warning" role="status"><?= e($data['zero_cost']) ?> sold item <?= $data['zero_cost']===1?'row has':'rows have' ?> zero recorded cost. Estimated profit may be overstated.</p><?php endif; ?></div>
    <?php if (!$print): ?><section class="dashboard-panel chart-panel" aria-labelledby="report-chart-title"><div class="panel-heading"><div><h2 id="report-chart-title">Sales, spending and profit</h2><p><?= e(ucfirst($data['chart']['grouping'])) ?> totals · Sales after discounts and operating expenses</p></div><div class="chart-legend"><span><i class="legend-dot sales-dot"></i>Sales</span><span><i class="legend-dot expenses-dot"></i>Expenses</span><span><i class="legend-dot report-profit-dot"></i>Net profit</span></div></div>
        <?php if ($data['chart']['has_activity']): ?><div class="financial-chart-wrap" data-report-chart="<?= e(json_encode($data['chart'],JSON_THROW_ON_ERROR)) ?>"><canvas id="report-chart" role="img" aria-label="Sales, operating expenses and estimated net profit for <?= e($filters['period']['label']) ?>. Values are available in the following table."></canvas><p class="chart-fallback" id="report-chart-fallback" hidden>The chart could not load. Use the chart data table below.</p></div>
        <details class="chart-data-table" id="report-chart-data"><summary>View chart data</summary><div class="table-responsive"><table class="table table-sm"><caption class="visually-hidden">Financial overview values in PHP</caption><thead><tr><th scope="col">Period</th><th scope="col" class="text-end">Sales</th><th scope="col" class="text-end">Expenses</th><th scope="col" class="text-end">Net profit</th></tr></thead><tbody><?php foreach ($data['chart']['labels'] as $index=>$label): ?><tr><th scope="row"><?= e($label) ?></th><?php foreach (['sales','expenses','profit'] as $key): ?><td class="text-end"><?= e(dashboard_money((int)round($data['chart'][$key][$index]*100))) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></details>
