    <p class="report-scope">Valid payments collected: <strong><?= e(sale_money($data['collections']['total'])) ?></strong> · Cash <?= e(sale_money($data['collections']['methods']['cash'])) ?> · Digital Wallet <?= e(sale_money($data['collections']['methods']['wallet'])) ?> · Bank Transfer <?= e(sale_money($data['collections']['methods']['bank'])) ?>. By payment date, excluding refunded amounts and voided sales. <a href="<?= e(app_url('user/payments.php').'?'.http_build_query(['period'=>'custom','start'=>$filters['period']['start']->format('Y-m-d'),'end'=>$filters['period']['end']->format('Y-m-d')])) ?>">View Payment Management</a></p>
    <section class="dashboard-panel report-panel" aria-labelledby="selected-report-title"><div class="panel-heading"><div><h2 id="selected-report-title"><?= e($titles[$filters['tab']]) ?></h2><p><?= $filters['tab']==='utang'?'Current balances across all sale dates · Collections use selected payment dates':e($filters['period']['label']).' · Posted transactions only' ?></p></div></div>
    <?php if ($filters['tab']==='profit'): ?>
        <div class="report-profit-layout"><div><dl class="report-profit-lines"><?php foreach (report_profit_lines($data) as [$label,$amount,$note]): ?><div class="<?= in_array($label,['Net sales','Gross profit','Estimated net profit'],true)?'report-profit-total':'' ?>"><dt><?= e($label) ?><span><?= e($note) ?></span></dt><dd class="<?= $amount<0?'amount-negative':'' ?>"><?= e(dashboard_money($amount)) ?></dd></div><?php endforeach; ?></dl><div class="report-cash-note"><strong>Payments received, less refunds: <?= e(dashboard_money($data['cash'])) ?></strong><p>Actual cash collected by payment date in this period, including initial payments and later collections. Refunds on voided sales are included. This is separate from sales revenue and profit.</p></div></div>
        <section class="report-products" aria-labelledby="report-products-title"><h3 id="report-products-title">Top-Selling Products</h3><p>Top five by sales value after allocated discounts. Names and costs use sale snapshots; the latest sold name is shown.</p><?php if (!$data['products']): ?><p>No products sold in this period.</p><?php else: ?><div class="table-responsive"><table class="table report-table report-products-table"><thead><tr><th scope="col">Product</th><th scope="col" class="text-end">Quantity</th><th scope="col" class="text-end">Sales</th><th scope="col" class="text-end">Est. gross profit</th></tr></thead><tbody><?php foreach (array_slice($data['products'],0,5) as $product): ?><tr><th scope="row"><?= e($product['name']) ?></th><td class="text-end"><?= e(rtrim(rtrim($product['quantity'],'0'),'.')) ?></td><td class="text-end"><?= e(dashboard_money($product['sales'])) ?></td><td class="text-end <?= $product['profit']<0?'amount-negative':'' ?>"><?= e(dashboard_money($product['profit'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p>Estimated gross contribution is sales after proportionally allocated transaction discounts minus historical item costs, before operating expenses.</p></section></div>
    <?php else: ?>
        <div class="report-facts">
