        <?php elseif ($filters['tab']==='expenses'): ?><div><span>Operating expenses</span><strong><?= e(dashboard_money($data['totals']['expenses'])) ?></strong></div><div><span>Expense count</span><strong><?= e($data['expense_count']) ?></strong></div><div><span>Highest expense category</span><strong><?= e($data['categories'][0]['category_name']??'No expenses') ?></strong></div>
