        <?php endif; ?></div>
        <?php if ($filters['tab']==='expenses' && $data['categories']): ?><details class="report-distribution"><summary>Expense distribution by category</summary><div class="table-responsive"><table class="table table-sm"><thead><tr><th scope="col">Category</th><th scope="col" class="text-end">Expenses</th><th scope="col" class="text-end">Amount</th><th scope="col" class="text-end">Share</th></tr></thead><tbody><?php foreach ($data['categories'] as $cat): ?><tr><th scope="row"><?= e($cat['category_name']) ?></th><td class="text-end"><?= e($cat['expenses']) ?></td><td class="text-end"><?= e(sale_money($cat['amount'])) ?></td><td class="text-end"><?= e(number_format(dashboard_cents($cat['amount'])/$data['totals']['expenses']*100,1)) ?>%</td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?>
