            <div class="report-search"><label for="report-search">Search <?= $filters['tab']==='expenses'?'description or category':'customer or reference' ?></label><input class="form-control form-control-sm" type="search" id="report-search" name="q" maxlength="100" value="<?= e($filters['q']) ?>"></div>
            <?php if ($filters['tab']==='expenses'): ?><div><label for="report-category">Category</label><select class="form-select form-select-sm" name="category" id="report-category"><option value="">All categories</option><?php foreach ($options as $cat): ?><option value="<?= e($cat['expense_category_id']) ?>" <?= $filters['category']===(string)$cat['expense_category_id']?'selected':'' ?>><?= e($cat['category_name']) ?></option><?php endforeach; ?></select></div>
